var syms = [['AAPL',234.18,232.76],['MSFT',512.40,515.55],['NVDA',178.44,175.56],
            ['AMZN',231.07,230.13],['META',604.12,609.52],['GOOGL',197.33,196.25],
            ['TSLA',421.66,428.88],['JPM',268.94,268.23],['XOM',118.52,118.96],
            ['SPY',596.31,595.12]];
var cells = root.querySelectorAll('.cell');
var clk = root.querySelector('.clk');
var n = syms.length;
var secs = 15 * 3600 + 42 * 60 + 8;
function two(v){ return v < 10 ? '0' + v : '' + v; }
function paint(i, flash){
  var s = syms[i], chg = s[1] - s[2], p = chg / s[2] * 100;
  for (var k = i; k < cells.length; k += n){
    var c = cells[k];
    c.className = 'cell ' + (chg >= 0 ? 'up' : 'dn') + (flash ? ' fl' : '');
    c.querySelector('.px').textContent = s[1].toFixed(2);
    c.querySelector('.cg').textContent = (chg >= 0 ? '▲ +' : '▼ ') + chg.toFixed(2);
    c.querySelector('.pc').textContent = (p >= 0 ? '+' : '') + p.toFixed(2) + '%';
  }
  if (flash) setTimeout(function(){
    for (var k2 = i; k2 < cells.length; k2 += n) cells[k2].classList.remove('fl');
  }, 700);
}
var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  var i = Math.floor(Math.random() * n), s = syms[i];
  var step = s[2] * (Math.random() - 0.5) * 0.0022;
  var nx = s[1] + step;
  if (nx > s[2] * 1.03) nx = s[2] * 1.03;
  if (nx < s[2] * 0.97) nx = s[2] * 0.97;
  s[1] = Math.round(nx * 100) / 100;
  paint(i, true);
}, 780);
var clock = setInterval(function(){
  if (!root.isConnected) { clearInterval(clock); return; }
  secs++;
  clk.textContent = two(Math.floor(secs / 3600) % 24) + ':' + two(Math.floor(secs / 60) % 60) + ':' + two(secs % 60);
}, 1000);

