var tape = root.querySelector('.tape');
var bidEl = root.querySelector('.bd'), askEl = root.querySelector('.ak');
var sprEl = root.querySelector('.sp'), fill = root.querySelector('.dbar i');
var bx = root.querySelector('.bx'), sx = root.querySelector('.sx'), dx = root.querySelector('.dx');
var exs = ['ARCA','NSDQ','NYSE','EDGX','BATS','IEX','MEMX'];
var bid = 596.28, ask = 596.30, buy = 412300, sell = 388100, ms = 0;
function two(v){ return v < 10 ? '0' + v : '' + v; }
function three(v){ return v < 10 ? '00' + v : (v < 100 ? '0' + v : '' + v); }
function grp(n){ return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
var clock = 15 * 3600000 + 42 * 60000 + 7418;
function stamp(){
  var s = Math.floor(clock / 1000);
  return two(Math.floor(s / 3600) % 24) + ':' + two(Math.floor(s / 60) % 60) + ':' + two(s % 60) + '.' + three(clock % 1000);
}
function cell(cls, txt){ var s = document.createElement('span'); s.className = cls; s.textContent = txt; return s; }
function totals(){
  var share = buy / (buy + sell) * 100;
  fill.style.width = share.toFixed(1) + '%';
  bx.textContent = 'BUY ' + grp(buy);
  sx.textContent = 'SELL ' + grp(sell);
  var d = buy - sell;
  dx.textContent = 'Δ ' + (d >= 0 ? '+' : '-') + grp(Math.abs(d));
}
function quote(){
  if (Math.random() < 0.34){
    var step = (Math.random() < 0.5 ? 0.01 : -0.01);
    bid = Math.round((bid + step) * 100) / 100;
    ask = Math.round((bid + 0.02) * 100) / 100;
    bidEl.textContent = bid.toFixed(2);
    askEl.textContent = ask.toFixed(2);
    sprEl.textContent = 'SPRD 0.02/' + (0.02 / ((bid + ask) / 2) * 10000).toFixed(2) + 'bp';
  }
}
function emit(){
  quote();
  var r = Math.random(), agg = r < 0.44 ? 'ask' : (r < 0.86 ? 'bid' : 'mid');
  var px = agg === 'ask' ? ask : (agg === 'bid' ? bid : (bid + ask) / 2);
  var sz = Math.random() < 0.14 ? (2 + Math.floor(Math.random() * 9)) * 1000 : (1 + Math.floor(Math.random() * 9)) * 100;
  if (agg === 'ask') buy += sz; else if (agg === 'bid') sell += sz;
  var row = document.createElement('div');
  row.className = 'row ' + agg + (sz >= 2000 ? ' blk' : '');
  row.appendChild(cell('tm', stamp()));
  row.appendChild(cell('px', px.toFixed(2)));
  row.appendChild(cell('sz', grp(sz)));
  row.appendChild(cell('ag', agg === 'ask' ? '@ASK' : (agg === 'bid' ? '@BID' : 'MID')));
  row.appendChild(cell('ex', exs[Math.floor(Math.random() * exs.length)]));
  tape.insertBefore(row, tape.firstChild);
  while (tape.children.length > 8) tape.removeChild(tape.lastChild);
  totals();
}
var loop = setInterval(function(){
  if (!root.isConnected) { clearInterval(loop); return; }
  ms += 120;
  clock += 120;
  if (ms >= 240 + Math.random() * 520){ ms = 0; emit(); }
}, 120);

