            ['MARA','LUDP',18.90],['NKLA','M',1.24],['HOOD','LUDP',42.18],['SOUN','T1',9.36]];
var secs = 19 * 3600 + 42 * 60 + 11;
var pi = 0, since = 0;
function two(v){ return v < 10 ? '0' + v : '' + v; }
function hms(s){ return two(Math.floor(s / 3600) % 24) + ':' + two(Math.floor(s / 60) % 60) + ':' + two(s % 60); }
function mmss(s){ return 'T-' + two(Math.floor(s / 60)) + ':' + two(s % 60); }
var items = [];
Array.prototype.forEach.call(root.querySelectorAll('.nt'), function(n, i){
  items.push({ el: n, state: i === 0 ? 1 : (i === 1 ? 2 : 3), left: i === 0 ? 107 : (i === 1 ? 42 : 0), halt: 0 });
});
function setState(it, st){
  it.state = st;
  var cls = st === 1 ? 'halted' : (st === 2 ? 'pend' : 'done');
  it.el.className = 'nt ' + cls;
  it.el.querySelector('.st').textContent = st === 1 ? 'HALTED' : (st === 2 ? 'RESUME PEND' : 'RESUMED');
