  }
  if (since >= 16){
    since = 0;
    var p = pool[pi % pool.length]; pi++;
    var last = p[2];
    var ind = Math.round(last * (1 + (Math.random() < 0.5 ? -1 : 1) * (0.03 + Math.random() * 0.06)) * 100) / 100;
