var lo = root.querySelector('.lo'), hi = root.querySelector('.hi'), mk = root.querySelector('.mk');
var cells = root.querySelectorAll('.ic');
var ix = [
  ['S&P 500', '.SPX', 5982.44, 5963.82, 5948.10, 5995.36],
  ['NASDAQ 100', '.NDX', 21438.70, 21352.15, 21301.44, 21470.90],
  ['DOW JONES', '.DJI', 43118.26, 43209.44, 43050.12, 43244.80],
  ['RUSSELL 2000', '.RUT', 2318.94, 2332.16, 2311.05, 2340.62],
  ['CBOE VIX', '.VIX', 14.82, 14.11, 14.02, 15.36]
