  var s = Math.abs(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (v < 0 ? '-' : '') + s;
}
function paint(flash){
  var r = ix[cur], chg = r[2] - r[3], p = chg / r[3] * 100;
  if (r[2] > r[5]) r[5] = r[2];
  if (r[2] < r[4]) r[4] = r[2];
  card.classList.remove(chg >= 0 ? 'dn' : 'up');
  card.classList.add(chg >= 0 ? 'up' : 'dn');
  nm.textContent = r[0];
  ric.textContent = r[1];
  lv.textContent = com(r[2]);
  cg.textContent = (chg >= 0 ? '▲ +' : '▼ ') + chg.toFixed(2);
  pc.textContent = (p >= 0 ? '+' : '') + p.toFixed(2) + '%';
  lo.textContent = com(r[4]);
  hi.textContent = com(r[5]);
  mk.style.left = ((r[2] - r[4]) / (r[5] - r[4]) * 100).toFixed(1) + '%';
  for (var i = 0; i < cells.length; i++){
    var q = ix[i], c2 = q[2] - q[3], p2 = c2 / q[3] * 100;
    cells[i].className = 'ic ' + (c2 >= 0 ? 'up' : 'dn') + (i === cur ? ' on' : '');
    cells[i].querySelector('i').textContent = (p2 >= 0 ? '+' : '') + p2.toFixed(2) + '%';
  }
  if (flash){
    lv.classList.remove('tick');
    void lv.offsetWidth;
    lv.classList.add('tick');
  }
