var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  var r = ix[Math.floor(Math.random() * ix.length)];
  r[2] = Math.round((r[2] + r[3] * (Math.random() - 0.5) * 0.0016) * 100) / 100;
  paint(true);
}, 1200);
