js:
var ls = root.querySelector('.ls');
var fill = root.querySelector('.tb i');
var lg = root.querySelector('.lg'), sh = root.querySelector('.sh'), rt = root.querySelector('.rt');
var tt = root.querySelector('.tt'), ev = root.querySelector('.ev'), mx = root.querySelector('.mx');
var pairs = [['BTCUSDT', 96318.5, 1], ['ETHUSDT', 3424.6, 2], ['SOLUSDT', 214.4, 2],
             ['XRPUSDT', 2.4462, 4], ['DOGEUSDT', 0.38142, 5], ['ETHUSDT', 3424.6, 2]];
var exs = ['BNC', 'BYB', 'OKX', 'HL', 'BMX'];
var longs = 412.8e6, shorts = 188.3e6, events = 18442, biggest = 8.41e6, wait = 0;
var clock = (15 * 3600 + 42 * 60 + 7) * 1000;
function two(v){ return v < 10 ? '0' + v : '' + v; }
function hms(ms){
  var s = Math.floor(ms / 1000);
  return two(Math.floor(s / 3600) % 24) + ':' + two(Math.floor(s / 60) % 60) + ':' + two(s % 60);
}
function usd(v){ return v >= 1e6 ? '$' + (v / 1e6).toFixed(2) + 'M' : '$' + Math.round(v / 1000) + 'K'; }
function com(v, d){
  var p = v.toFixed(d).split('.');
  return p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',') + (p[1] ? '.' + p[1] : '');
}
function span(cls, txt){ var s = document.createElement('span'); s.className = cls; s.textContent = txt; return s; }
function totals(){
  var share = longs / (longs + shorts) * 100;
  fill.style.width = share.toFixed(1) + '%';
  lg.textContent = 'LONGS $' + (longs / 1e6).toFixed(1) + 'M';
  sh.textContent = 'SHORTS $' + (shorts / 1e6).toFixed(1) + 'M';
  rt.textContent = share.toFixed(1) + ' / ' + (100 - share).toFixed(1);
  tt.textContent = '$' + ((longs + shorts) / 1e6).toFixed(1) + 'M';
  ev.textContent = String(events).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  mx.textContent = usd(biggest);
}
function emit(){
  var p = pairs[Math.floor(Math.random() * pairs.length)];
  var lng = Math.random() < 0.66;
  var sz = 8000 * Math.pow(3.2e6 / 8000, Math.pow(Math.random(), 2.2));
  var px = p[1] * (1 + (lng ? -1 : 1) * Math.random() * 0.0016);
  var row = document.createElement('div');
  row.className = 'row ' + (lng ? 'lng' : 'sht') + (sz >= 1e6 ? ' wh' : '') + ' new';
  var bar = document.createElement('i');
  bar.className = 'mag';
  bar.style.width = Math.min(100, Math.log(sz / 8000) / Math.log(3.2e6 / 8000) * 100).toFixed(0) + '%';
  row.appendChild(bar);
  row.appendChild(span('tm', hms(clock)));
  row.appendChild(span('pr', p[0]));
  row.appendChild(span('sd', lng ? 'LONG' : 'SHORT'));
  row.appendChild(span('sz', usd(sz)));
  row.appendChild(span('px', com(px, p[2])));
  row.appendChild(span('ex', exs[Math.floor(Math.random() * exs.length)]));
  ls.insertBefore(row, ls.firstChild);
  while (ls.children.length > 6) ls.removeChild(ls.lastChild);
  setTimeout(function(){ row.classList.remove('new'); }, 600);
  if (lng) longs += sz; else shorts += sz;
  events++;
  if (sz > biggest) biggest = sz;
  totals();
}
var loop = setInterval(function(){
  if (!root.isConnected) { clearInterval(loop); return; }
  wait -= 200;
  clock += 200;
  if (wait <= 0){ wait = 420 + Math.random() * 1100; emit(); }
}, 200);
